    "effectZh": "[Raid] \n〈虎杖 悠仁〉激活，并可以移动到前线 L\n[Impact（1）]\n（攻击并在战斗中获胜时，对对手玩家造成 1 点伤害）\n[登场时]\n从以下选项中『选择 1 个』。当自己场外有 3 张〈宿傩的指〉时，变为『选择 2 个』。当自己场外有 4 张或更多〈宿傩的指〉时，变为『全部』。\n・抽 1 张牌，对手将自身手札中的 1 张置入场外。\n・BP2500 以上的对手的 frontline L 的所有角色在本回合中，BP-2000。\n・选择 BP3500 以下的对手的 frontline L 的角色至多 1 枚，使其退场。",
    "trigger": "[レイド]\nこのカードを手札に加えるか、必要エナジーを満たしている場合、レイドさせる。",
